// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Load font at module level to prevent flickering
const { fontFamily: playfairFamily } = loadPlayfair();



export type YouVsSmokerProps = Record<string, any>;

const checkpointsData = [
  { label: "INHALE", y: 0, showBlue: true },
  { label: "HOLD", y: 150, showBlue: true },
  { label: "SMOKER", y: 550, showBlue: true },
  { label: "VAPER", y: 950, showBlue: true },
  { label: "NORMAL", y: 1350, showBlue: false },
  { label: "ATHLETE", y: 1750, showBlue: false },
];

const YouVsSmoker: React.FC<YouVsSmokerProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 60,
  leftColor = "#00FF00",
  rightColor = "#0066FF",
  emoji = "😖",
  titleLeft = "YOU",
  titleCenter = "VS",
  titleRight = "SMOKER",
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Dynamically calculate animation frames based on total duration
  const totalFrames = durationInSeconds * fps;
  const numCheckpoints = checkpointsData.length;

  // Generate strictly ascending frame markers for continuous movement
  const timingFrames: number[] = [];
  const vGreen: number[] = [];
  const vBlue: number[] = [];
  
  const vaperY = checkpointsData.find((c) => c.label === "VAPER")?.y || 950;

  for (let i = 0; i < numCheckpoints; i++) {
    // Distribute time evenly across checkpoints without pausing
    timingFrames.push((i / (numCheckpoints - 1)) * totalFrames);
    
    const yVal = checkpointsData[i].y;
    vGreen.push(yVal);
    
    // Blue stops updating its Y position once it hits the VAPER checkpoint
    const blueYVal = yVal > vaperY ? vaperY : yVal;
    vBlue.push(blueYVal);
  }

  // Apply a global ease-in-out to the frame progress
  const easedFrame = interpolate(frame, [0, totalFrames], [0, totalFrames], {
    easing: Easing.bezier(0.42, 0, 0.58, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Interpolate positions continuously
  const greenY = interpolate(easedFrame, timingFrames, vGreen, {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.linear,
  });

  const blueY = interpolate(easedFrame, timingFrames, vBlue, {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.linear,
  });

  // Calculate Camera Scroll: Start scrolling when Green passes SMOKER (y=550)
  const scrollStart = 550;
  const maxScroll = checkpointsData[checkpointsData.length - 1].y - scrollStart;
  
  const scrollOffset = interpolate(
    greenY,
    [scrollStart, checkpointsData[checkpointsData.length - 1].y],
    [0, maxScroll],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Layout constants
  const trackStartY = 350;
  const leftX = "35%";
  const rightX = "65%";
  const greenTrackHeight = checkpointsData[checkpointsData.length - 1].y;
  const blueTrackHeight = vaperY;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: playfairFamily, overflow: "hidden" }}>
      
      {/* Fixed Header Title */}
      <div
        style={{
          position: "absolute",
          top: 80,
          width: "100%",
          display: "flex",
          justifyContent: "center",
          gap: "24px",
          fontSize: "70px",
          fontWeight: 900,
          zIndex: 10,
          textTransform: "uppercase",
        }}
      >
        <span style={{ color: "transparent", WebkitTextStroke: `3px ${leftColor}` }}>
          {titleLeft}
        </span>
        <span style={{ color: "transparent", WebkitTextStroke: "3px #FFFFFF" }}>
          {titleCenter}
        </span>
        <span style={{ color: "transparent", WebkitTextStroke: `3px ${rightColor}` }}>
          {titleRight}
        </span>
      </div>

      {/* Scrolling Container */}
      <div
        style={{
          position: "absolute",
          top: trackStartY,
          left: 0,
          width: "100%",
          height: `${greenTrackHeight + 500}px`,
          transform: `translateY(-${scrollOffset}px)`,
        }}
      >
        {/* Left Green Track Line */}
        <div
          style={{
            position: "absolute",
            left: leftX,
            top: 0,
            width: "16px",
            height: `${greenTrackHeight}px`,
            backgroundColor: leftColor,
            transform: "translateX(-50%)",
            borderRadius: "10px",
            boxShadow: `0 0 15px 5px ${leftColor}80`,
            display: "flex",
            justifyContent: "center",
          }}
        >
          {/* Inner white core */}
          <div style={{ width: "4px", height: "100%", backgroundColor: "#fff", borderRadius: "2px" }} />
        </div>

        {/* Right Blue Track Line */}
        <div
          style={{
            position: "absolute",
            left: rightX,
            top: 0,
            width: "16px",
            height: `${blueTrackHeight}px`,
            backgroundColor: rightColor,
            transform: "translateX(-50%)",
            borderRadius: "10px",
            boxShadow: `0 0 15px 5px ${rightColor}80`,
            display: "flex",
            justifyContent: "center",
          }}
        >
           {/* Inner white core */}
           <div style={{ width: "4px", height: "100%", backgroundColor: "#fff", borderRadius: "2px" }} />
        </div>

        {/* Checkpoints & Labels */}
        {checkpointsData.map((cp, idx) => (
          <React.Fragment key={`cp-${idx}`}>
            {/* Left Dot */}
            <div
              style={{
                position: "absolute",
                left: leftX,
                top: cp.y,
                width: "48px",
                height: "48px",
                backgroundColor: leftColor,
                border: "4px solid white",
                borderRadius: "50%",
                transform: "translate(-50%, -50%)",
                boxShadow: `0 0 20px 5px ${leftColor}80`,
                zIndex: 2,
              }}
            />
            
            {/* Right Dot (Conditionally rendered for blue track) */}
            {cp.showBlue && (
              <div
                style={{
                  position: "absolute",
                  left: rightX,
                  top: cp.y,
                  width: "48px",
                  height: "48px",
                  backgroundColor: rightColor,
                  border: "4px solid white",
                  borderRadius: "50%",
                  transform: "translate(-50%, -50%)",
                  boxShadow: `0 0 20px 5px ${rightColor}80`,
                  zIndex: 2,
                }}
              />
            )}

            {/* Center Text Label */}
            <div
              style={{
                position: "absolute",
                left: "50%",
                top: cp.y,
                transform: "translate(-50%, -50%)",
                color: "#FFFFFF",
                fontSize: "36px",
                fontWeight: 700,
                letterSpacing: "0.1em",
                textShadow: "0px 4px 10px rgba(0,0,0,0.8)",
                zIndex: 1,
              }}
            >
              {cp.label}
            </div>
          </React.Fragment>
        ))}

        {/* Left Green Emoji */}
        <div
          style={{
            position: "absolute",
            left: leftX,
            top: greenY,
            transform: "translate(-50%, -50%)",
            fontSize: "80px",
            zIndex: 5,
            filter: "drop-shadow(0px 10px 10px rgba(0,0,0,0.5))",
          }}
        >
          {emoji}
        </div>

        {/* Right Blue Emoji */}
        <div
          style={{
            position: "absolute",
            left: rightX,
            top: blueY,
            transform: "translate(-50%, -50%)",
            fontSize: "80px",
            zIndex: 5,
            filter: "drop-shadow(0px 10px 10px rgba(0,0,0,0.5))",
          }}
        >
          {emoji}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default YouVsSmoker;